TARGET_ANSWERS = 'BCADBCADCB'

def make(i, row):
    tag, prompt, opts, answer, reason = row
    correct_index = opts.index(answer)
    target = TARGET_ANSWERS[i - 1]
    distractors = [text for index, text in enumerate(opts) if index != correct_index]
    position = ord(target) - 65
    arranged = distractors[:position] + [answer] + distractors[position:]
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(arranged)]
    aid = target
    steps = [f'讀題定位：圈出「{tag}」以及效益、成本、風險、生命週期、利害關係人或不確定性。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合能源方案的多準則決策。', '排除誘答：分清單一技術指標與完整系統評估，不把低機率當成零風險，也不忽略公平與資料界線。', '最後回查：確認比較的功能單位、時間範圍、資料來源及決策參與都足以支持結論。']
    return {'id': f'question-science-content-nc-iv-2-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-nc-iv-2'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason + f' 正確答案為選項 {aid}：「{answer}」。'}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究能源方案、生命週期、風險、外部成本、公平轉型與情境決策的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-13', 'lessonId': 'lesson-science-content-nc-iv-2', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '能源開發的風險評估與決策', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先列出方案的效益、成本、生命週期與風險，再檢查資料可比性、情境不確定性與社會公平，最後形成可追溯決策。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-nc-iv-2-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
